using Xunit;

namespace Juego.Tests;

public class FizzBuzzTests
{
    [InlineData(1, "1")]
    [InlineData(3, "Fizz")]
    [InlineData(5, "Buzz")]
    [InlineData(9, "Fizz")]
    [InlineData(10, "Buzz")]
    [InlineData(15, "FizzBuzz")]
    [InlineData(30, "FizzBuzz")]
    [InlineData(7, "7")]
    [Theory]
    public void Convertir(int n, string expected) =>
        Assert.Equal(expected, FizzBuzz.Convertir(n));
}

