namespace Juego;

public static class FizzBuzz
{
    public static string Convertir(int n) =>
        n % 3 == 0 ? "Fizz" : n + "";
}

namespace Juego;

public static class FizzBuzz
{
    public static string Convertir(int n) =>
        n % 3 == 0 && n % 5 == 0 ? "FizzBuzz"
        : n % 3 == 0 ? "Fizz"
        : n % 5 == 0 ? "Buzz"
        : n + "";
}

